effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     // const int MAX_RAY_STEPS = 64;
     // const int MENGER_ITERATIONS = 3;
     const float RAY_STOP_TRESHOLD = 0.0001;

     float maxcomp(vec2 v) { return max(v.x, v.y); }

     float sdCross(vec3 p) {
     	p = abs(p);
     	vec3 d = vec3(max(p.x, p.y),
     				  max(p.y, p.z),
     				  max(p.z, p.x));
     	return min(d.x, min(d.y, d.z)) - (1.0 / 3.0);
     }

     float sdCrossRep(vec3 p) {
     	vec3 q = mod(p + 1.0, 2.0) - 1.0;
     	return sdCross(q);
     }

     float sdCrossRepScale(vec3 p, float s) {
     	return sdCrossRep(p * s) / s;	
     }

     float scene(vec3 p) {
     	float scale = 1.0;
     	float dist = 0.0;
     	for (int i = 0; i < int(MENGER_ITERATIONS); i++) {
     		dist = max(dist, -sdCrossRepScale(p, scale));
     		scale *= 3.0;
     	}
     	return dist;
     }

     vec3 hsv2rgb(vec3 c)
     {
         vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
         vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
         return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
     }

     vec4 colorize(float c) {

     	float hue = mix(0.6, 1.15, min(c * 1.2 - 0.05, 1.0));
     	float sat = 1.0 - pow(c, 4.0);
     	float lum = c;
     	vec3 hsv = vec3(hue, sat, lum);
     	vec3 rgb = hsv2rgb(hsv);
     	return vec4(rgb, 1.0);	
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = acTime;

     vec2 umefx;
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;
     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

     	vec2 screenPos = umefx;
     	vec2 mousePos = iMouse.xy / iResolution.xy * 2.0 - 1.0;

     	vec3 cameraPos = vec3(xxx.x*0.01, xxx.y*0.01, xxx.z*0.01);
     	vec3 cameraDir = vec3(yyy.x*0.01, yyy.y*0.01, yyy.z*0.01);
     	vec3 cameraPlaneU = vec3(zzz.x*0.01, zzz.y*0.01, zzz.z*0.01);
     	vec3 cameraPlaneV = vec3(www.x*0.01, www.y*0.01, www.z*0.01) * (iResolution.y / iResolution.x);

     	vec3 rayPos = cameraPos;
     	vec3 rayDir = cameraDir + screenPos.x * cameraPlaneU + screenPos.y * cameraPlaneV;

     	rayDir = normalize(rayDir);

     	float dist = scene(rayPos);
     	int stepsTaken;
     	for (int i = 0; i < int(MAX_RAY_STEPS); i++) {
     		if (dist < RAY_STOP_TRESHOLD) {
     			continue;
     		}
     		rayPos += rayDir * dist;
     		dist = scene(rayPos);
     		stepsTaken = i;
     	}

     	vec4 color = colorize(pow(float(stepsTaken) / MAX_RAY_STEPS, 0.9));

     	fragColor = color;

 	vec4 factor = mix(texColorX,fragColor,1.0);

 	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         vec4 gradmap;
         float luminance = dot(fragColor.rgb, luminanceWeighting);
         gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

     vec4 resultfinal;
       if( blendMode==0 ) {
         resultfinal = (factor * hardness) * texColor.a; }
         // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; 
         resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
       }
     }
